import{_ as t,o as d,c as o,a0 as r}from"./chunks/framework.CR-yHhk1.js";const m=JSON.parse('{"title":"CLI and environment","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md"}'),s={name:"reference/cli.md"};function a(c,e,i,n,l,h){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="cli-and-environment" tabindex="-1">CLI and environment <a class="header-anchor" href="#cli-and-environment" aria-label="Permalink to &quot;CLI and environment&quot;">​</a></h1><p>The <code>sepia</code> command&#39;s surface and the environment variables the plane reads. <code>sepia --help</code> is authoritative; this page is the map.</p><p>There is no hand-rolled <code>sepia</code> binary: the command ships as the tamias pack in <code>libraries/sepia/</code> — a generated <code>bins[]</code> shim that runs <code>tamias-driver-sepia cli</code> → <code>sepia_cli::run_from</code> in-process (T-012). Every verb below behaves identically through the shim.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><p>Top-level store verbs are aliases for the <code>store</code> namespace — <code>sepia list</code> ≡ <code>sepia store list</code>, and so on.</p><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>sepia driver list [--json]</code></td><td>Discovery: the <code>sepia-driver-*</code> binaries found, their probed manifests, and whether each agent command resolves. <code>sepia driver</code> alone lists them.</td></tr><tr><td><code>sepia list</code></td><td>List sessions in a store (<code>store list</code>).</td></tr><tr><td><code>sepia export &lt;id&gt; [out] [--format json|cline]</code></td><td>Session IR JSON to stdout/a file; <code>--format cline</code> writes Cline session files instead (out is then a directory).</td></tr><tr><td><code>sepia import &lt;source&gt; [--to &lt;agent&gt;] [--session-id &lt;id&gt;] [--force]</code></td><td>Import a Cline session dir, a Claude <code>.jsonl</code> transcript, or a session JSON export into a store.</td></tr><tr><td><code>sepia install &lt;id&gt; [--from &lt;a&gt;] [--to &lt;b&gt;] [--id &lt;id&gt;] [--force]</code></td><td>Copy a session into a store ready to resume — <code>cline</code> (default), <code>claude</code>, <code>cursor</code>, or <code>devin</code>.</td></tr><tr><td><code>sepia delete &lt;id&gt; [--from &lt;agent&gt;]</code></td><td>Delete a session from a store.</td></tr><tr><td><code>sepia config list|export|import|install|diff</code></td><td>Agent config IR ops — rules/skills/commands/hooks/subagents/MCP. See <a href="./agent-configs.html">agent configs</a>.</td></tr><tr><td><code>sepia serve</code></td><td>The session plane — ndjson JSON-RPC on stdio. See <a href="./serve-wire.html">serve wire</a>.</td></tr><tr><td><code>sepia version</code></td><td>Version stamp.</td></tr></tbody></table><p>Store flags (<code>--devin-dir</code>, <code>--claude-dir</code>, <code>--cursor-dir</code>, <code>--cline-dir</code>) pick the store directory and imply the agent when <code>--from</code>/<code>--to</code> is omitted.</p><h2 id="the-driver-ops-surface" tabindex="-1">The driver ops surface <a class="header-anchor" href="#the-driver-ops-surface" aria-label="Permalink to &quot;The driver ops surface&quot;">​</a></h2><p><code>tamias-driver-sepia</code> doubles as the generated-surface driver (P-021). <code>ops</code> answers an ops manifest derived from the clap tree: every bounded verb is a <code>cli.&lt;verb&gt;</code> wire query — <code>driver</code>, <code>list</code>, <code>export</code>, <code>import</code>, <code>install</code>, <code>delete</code>, <code>config</code>, <code>version</code> and friends, 18 ops total — dispatched through <code>sepia_cli::run_from</code> in a captured child. <code>run &lt;argv&gt;</code> is the raw passthrough; <code>cli &lt;argv&gt;</code> is the <code>bins[]</code> shim verb the <code>sepia</code> command itself execs (inherited stdio, so <code>sepia serve</code> streams end-to-end). <code>serve</code> is listed under <code>surfaces</code>, never an op — it never returns. A feature-gated <code>mcp</code> mode renders the same manifest as MCP tools via pavo-driver-kit.</p><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h2><p>Read by <code>sepia serve</code> and the store verbs; driver discovery and store paths apply to the <code>serve</code> child, so set them in its environment.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>SEPIA_HOME</code></td><td>platform data dir</td><td>sepia&#39;s own state dir (<code>node.json</code>, meta overlay)</td></tr><tr><td><code>SEPIA_NODE</code></td><td>—</td><td>node identity written into <code>node.json</code></td></tr><tr><td><code>SEPIA_NAME</code></td><td>—</td><td>display name for this node</td></tr><tr><td><code>SEPIA_DRIVER_DIR</code></td><td>—</td><td>extra driver discovery dir (first in order)</td></tr><tr><td><code>SEPIA_CLAUDE_DIR</code></td><td><code>~/.claude</code></td><td>Claude Code config/session dir</td></tr><tr><td><code>SEPIA_CURSOR_DIR</code></td><td><code>~/.cursor</code></td><td>Cursor dir</td></tr><tr><td><code>SEPIA_CLINE_DIR</code></td><td>cwd</td><td>Cline dir</td></tr><tr><td><code>SEPIA_DEVIN_DIR</code></td><td>platform data dir</td><td>Devin CLI dir</td></tr><tr><td><code>SEPIA_DEVIN_DB</code></td><td><code>&lt;devin dir&gt;/sessions.db</code></td><td>Devin sessions SQLite path</td></tr><tr><td><code>SEPIA_DEVIN_READONLY</code></td><td>off</td><td>open the Devin DB read-only</td></tr><tr><td><code>SEPIA_AGENT_&lt;ID&gt;_COMMAND</code></td><td>—</td><td>override the agent CLI command per driver (e.g. <code>SEPIA_AGENT_CLAUDE_COMMAND</code>)</td></tr><tr><td><code>SEPIA_EVENT_BUFFER</code></td><td>—</td><td>session-event buffer size</td></tr><tr><td><code>SEPIA_IDLE_TTL_MS</code></td><td>—</td><td>idle session TTL</td></tr><tr><td><code>SEPIA_SWEEP_MS</code></td><td>—</td><td>sweeper interval</td></tr><tr><td><code>SEPIA_LOCK_TTL_MS</code></td><td>—</td><td>session lock TTL</td></tr><tr><td><code>SEPIA_HISTORY_LIMIT</code></td><td>—</td><td>prompt-history cap</td></tr><tr><td><code>SEPIA_OTEL_ENDPOINT</code></td><td>—</td><td>OTLP endpoint (opt-in telemetry)</td></tr><tr><td><code>SEPIA_OTEL_SERVICE_NAME</code></td><td>—</td><td>OTEL service name</td></tr><tr><td><code>SEPIA_INHERIT_ENV</code></td><td>—</td><td>env vars passed through to agent subprocesses</td></tr><tr><td><code>SEPIA_DEBUG</code></td><td>—</td><td>debug logging</td></tr><tr><td><code>SEPIA_BIN</code></td><td>—</td><td>path to a <code>sepia</code>-shaped executable the view driver spawns for <code>serve</code> (the tamias shim, a legacy binary, or a test fake)</td></tr></tbody></table>',12)])])}const v=t(s,[["render",a]]);export{m as __pageData,v as default};
